  var meetsRaw;
  var $inputSearch = $('#inputSearch');
$(function() {
  
  var defaultForty = [];
  var timeoutId;
  function start(data) {
  meetsRaw = data;
  var cap = 1;
  var stopper = 61; 
  while(cap < 61 && data[data.length - cap] != undefined) {
    defaultForty.push(data[data.length - cap]);
    cap = cap + 1;
  }

  timeoutID = window.setTimeout(search, 1);
  var $result = $('#results'),
  
  $authorCheckbox = $('#author'),
  $titleCheckbox = $('#title'),
  $caseCheckbox = $('#case'),
  
  isCaseSensitive = false,
  
  fuse;
  
  function search() {
  var r = fuse.search($inputSearch.val());
  $result.empty();
  
  var results = [];

  r =  setFilters(r);
  
  if ($inputSearch.val() == "") {

    var iter = 0;
    while (iter < defaultForty.length) {
        results.push(new meet(defaultForty[iter].date_begin, defaultForty[iter].name, defaultForty[iter].venue_state, defaultForty[iter].sport, defaultForty[iter].meet_hnd, defaultForty[iter].reg_status, defaultForty[iter].reg_message, defaultForty[iter].public_registration, defaultForty[iter].hs, defaultForty[iter].college, defaultForty[iter].jcollege, defaultForty[iter].club, defaultForty[iter].jhs));
        iter = iter + 1;
    }
  }

  $.each(r, function() {
         
         //$result.append('<li class="result-item">' + this.name + ', <span>' + this.sport + '</span></li>');
         //fill an array with result objects
         results.push(new meet(this.date_begin, this.name, this.venue_state, this.sport, this.meet_hnd, this.reg_status, this.reg_message));

         });


  results = results.sort(sortResultsByDate);
    var tableString = "<table id='myTable' class='tablesorter' border='0' cellpadding='0' cellspacing='1'><thead><tr><th class='header'>Date</th><th class='header'>Meet Name</th><th class='header'>Sport</th><th class='header'>State</th><th class='header'>Registration</th></tr></thead><tbody>";
    var limit = 0;
    var flipFlop = 0;
    while (limit  < results.length ) {
        if(flipFlop % 2 == 0){
            tableString += "<tr class='odd'>";
        } else {
            tableString += "<tr class='even'>";
        }
  
        flipFlop += 1;
        tableString += "<td style='padding-left: 7px;'>" + dateFormatter(results[limit].date) + "</td><td><a class='meetLink' href='/meets/" + results[limit].sport + "/" + results[limit].meet_hnd + ".html'>" + unescape(results[limit].name) + "</a></td><td>";
  
        if(results[limit].sport == "track") {
            tableString += "TF";
        } else if (results[limit].sport == "swimming") {
            tableString += "SW";
        } else {
            tableString += "XC";
        }

        tableString += "</td><td>" + results[limit].state + "</td><td style='padding-left: 15px; width: 110px;'>";

        if(results[limit].reg_status == 200) {
          var datePattern = /\d{1,2}\/\d\d?\/\d{2}/;
          tableString += "<span class='label label-info'>has been PAUSED.</span></td></tr>";
        }else if(results[limit].reg_status == 3) {
          var datePattern = /\d{1,2}\/\d\d?\/\d{2}/;
          tableString += "<span class='label label-info'>Begins " + datePattern.exec(unescape(results[limit].reg_message)) + "</span></td></tr>";
        } else if (results[limit].reg_status == 6) {
          tableString += "<span class='label label-success'>Open</span></td></tr>";
        } else {
          tableString += "<span class='label'>Closed</span></td></tr>";
        }

        limit += 1;
    }
  
  tableString += "</tbody></table>";
  var target = document.getElementById('tableDiv');
  target.innerHTML = tableString;
  $("#myTable").tablesorter();
  $("#myTable").fadeIn('slow', function() {
        infiniteScrollEnabled = 1;
    });
  
  }
  
  function meet(date, name, state, sport, meet_hnd, reg_status, reg_message, ind, hs, col, jc, club, jhs) {
    this.date = date;
    this.name = name;
    this.state = state;
    this.sport = sport;
    this.meet_hnd = meet_hnd;
    this.reg_status = reg_status;
    this.reg_message = reg_message;
    this.ind = ind;
    this.hs = hs;
    this.col = col;
    this.jc = jc;
    this.club = club;
    this.jhs = jhs;
  }
  function dateFormatter(date) {
    return date.substring(5,7) + "/" + date.substring(8,10) + "/" + date.substring(0,4);
  }
  function createFuse() {
  var keys = ['name'];

  fuse = new Fuse(data, {
                  keys: keys,
                  caseSensitive: isCaseSensitive,
                  threshold: 0.2
                  });
  }
  
  function sortResultsByDate(a, b){
      var dateA=new Date(a.date), dateB=new Date(b.date)
	  return dateA-dateB; //sort by date ascending
	  }

function setFilters(fuseSearched) {

        //lists of all filter element ids on page 
        var reg_filters = new Array("ind_f", "hs_f", "jhs_f", "col_f", "jcol_f", "club_f");
        var reg_status_filters = new Array("open_f", "future_f", "closed_f");
        var sport_filters = new Array("xc_f", "tf_filter", "sw_f", "indoor_f", "outdoor_f");

        //hash table of key (id) value (checked or not checked) pairs of filters 
        var f = setHash(reg_filters, reg_status_filters, sport_filters);
        var filter_on_list = [];

        //handle reg_status filters
        if(f['open_f'] == 0 && f['closed_f'] == 0 && f['future_f'] == 0) {
            //don't filter anything [else there wouldn't be any results]
        } else {
            //remove where filter == 0
            if(f['open_f'] == 0) {
                filter_on_list.push('open_f');
            }
            if(f['closed_f'] == 0) {
                filter_on_list.push('closed_f');
            }
            if(f['future_f'] == 0) {
                filter_on_list.push('future_f');
            }
        }

        //handle sport filters
        if(f['xc_f'] == 0 && f['sw_f'] == 0 && f['tf_filter'] == 0) {
            //don't filter anything [else there wouldn't be any results]
        } else {
            //remove where filter == 0
            if(f['xc_f'] == 0) {
                filter_on_list.push('xc_f');
            }
            if(f['sw_f'] == 0) {
                filter_on_list.push('sw_f');
            }
            if(f['tf_filter'] == 0) {
                filter_on_list.push('tf_filter');
            } 
        }

        //handle season filters
        if(f['indoor_f'] == 0 && f['outdoor_f'] == 0) {
            //don't filter anything
        } else {
            //remove where filter == 0
            if(f['indoor_f'] == 0) {
                filter_on_list.push('indoor_f');
            }
            if(f['outdoor_f'] == 0) {
                filter_on_list.push('outdoor_f');
            }
        }

        //handle registration type filters 
        if(f['ind_f'] == 0 && f['club_f'] == 0 && f['hs_f'] == 0 && f['jhs_f'] == 0 && f['col_f'] == 0 && f['jcol_f'] == 0) {
            //don't filter anything [else there wouldn't be any results]
        } else {
            //we only want to filter out results that do not allow the checked filter
            //so effectively these filters will work backwards 
            if(f['ind_f'] == 1) {
                filter_on_list.push('ind_f');
            }
            if(f['club_f'] == 1) {
                filter_on_list.push('club_f');
            }
            if(f['hs_f'] == 1) {
                filter_on_list.push('hs_f');
            }
            if(f['jhs_f'] == 1) {
                filter_on_list.push('jhs_f');
            }
            if(f['col_f'] == 1) {
                filter_on_list.push('col_f');
            }
            if(f['jcol_f'] == 1) {
                filter_on_list.push('jcol_f');
            }
        }


        var moreResults = [];
        var x = 1;
        while(x < listSize - 1) {
            if(typeof fuseSearched[fuseSearched.length - x] != 'undefined') {
                if(notFiltered(fuseSearched[fuseSearched.length - x], filter_on_list) && stateCheck(fuseSearched[fuseSearched.length - x]) && datesRange(fuseSearched[fuseSearched.length - x])) {
                    moreResults.push(fuseSearched[fuseSearched.length - x]);
                    x = x + 1;
                } else {
                    x = x + 1;
                    listSize = listSize + 1;
                }
            } else {
                if(result_message == 1) {
                    result_message = 0;
                   // infiniteScrollEnabled = 0;
                   // window.setTimeout(displayResultMessage, 1500);
                }
                break;
            }
        }
        return moreResults; 
    }
  
  $inputSearch.on('keyup', search);
  createFuse();
  }
  
  $( document ).ready(function() {   
            start(data);
            });
  
  });


